/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: db, read, track, tracklist, row, storeTracklist, hex
 *   Constants: admin, user, album
 *   Variables: harness, server, base, token, userToken
 * Tests
 *   - members follow the declared Album order with each lifecycle state and only allowlisted fields
 *   - an empty Album lists no members, and an oversized membership reads only its leading bound
 *   - a legacy Album without declared IDs lists its ready linked MediaTracks by title, as listeners receive them
 *   - only a current administrator reads members, and only of a ready Album
 *   - expected rows place members by Disc and Track Number whatever their state or visibility, and a row without one has no file
 *   - renumbering, unlinking and deleting members change which rows have a file, never the stored tracklist
 *   - an iTunes, malformed, empty-Album, hidden-Album, legacy and oversized read
 *   - only administrators read expected rows, and listeners receive nothing new
 * @end-catalog */

import assert from 'node:assert/strict';
import type { Server } from 'node:http';
import { after, before, beforeEach, test } from 'node:test';
import { randomUUID } from 'node:crypto';
import { ObjectId } from 'mongodb';
import { createApp } from '../../src/app';
import { getDb } from '../../src/infrastructure/database';
import { adminCatalogItemRevision, editAdminCatalogItem, getAdminCatalogItem } from '../../src/administration/catalog/adminCatalogService';
import { ADMIN_ALBUM_TRACKS_LIMIT, getAdminCatalogAlbumTracks } from '../../src/administration/catalog/adminCatalogAlbumTracks';
import { createSession } from '../../src/services/auth/authSessionService';
import { expectedTracklistForStorage, type ExpectedTracklistRow } from '../../src/services/catalog/albumExpectedTracklist';
import { getListenerAlbum } from '../../src/services/listener/listenerContentService';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';

let harness: MongoReplicaSetHarness, server: Server, base = '', token = '', userToken = '';
const admin = new ObjectId(), user = new ObjectId(), album = new ObjectId();
const db = () => getDb()!;
const read = (id: string, access = token) => fetch(`${base}/api/admin/v1/catalog/album/${id}/tracks`, {
    headers: access ? { Authorization: `Bearer ${access}` } : {}
});
/** A ready Audio MediaTrack of the Album carrying private fields the projection must never return. */
const track = (_id: ObjectId, title: string, extra: Record<string, unknown> = {}) => ({
    _id, title, uploadStatus: 'ready', publicationStatus: 'ready', s3Key: `audio/${_id}/${new ObjectId()}`, albumId: album.toHexString(),
    originalFileName: 'private-source-name.flac', createdBy: admin.toHexString(), contentType: 'audio/flac',
    musicBrainzId: '11111111-2222-4333-8444-555555555555', coverArtUrl: 'https://private.example.test/cover.jpg', ...extra
});

/** A stored expected tracklist as its writer would store it: parser output with a Date. */
const tracklist = (rows: ExpectedTracklistRow[], source = 'musicbrainz') => {
    const built = expectedTracklistForStorage(source, new Date('2026-10-20T08:00:00.000Z'), rows);
    assert.ok(built.ok); return built.tracklist;
};
const row = (discNumber: number, trackNumber: number, durationMs: number | null = null): ExpectedTracklistRow =>
    ({ discNumber, trackNumber, title: `Expected row ${discNumber}-${trackNumber}`, durationMs });
const storeTracklist = (value: unknown, id = album) => db().collection('albums').updateOne({ _id: id }, { $set: { expectedTracklist: value } });
const hex = (id: ObjectId) => id.toHexString();

before(async () => {
    harness = await startMongoReplicaSet('archtree-admin-album-tracks-test');
    server = await new Promise(resolve => { const active = createApp().listen(0, '127.0.0.1', () => resolve(active)); });
    const address = server.address(); assert.ok(address && typeof address !== 'string'); base = `http://127.0.0.1:${address.port}`;
});
beforeEach(async () => {
    for (const name of ['users', 'authSessions', 'albums', 'audioTracks', 'artists', 'adminCatalogMutations']) await db().collection(name).deleteMany({});
    const adminUser = { _id: admin, role: 'admin', emailVerified: true, email: 'tracks-admin@example.test' };
    const ordinary = { _id: user, role: 'user', emailVerified: true, email: 'tracks-user@example.test' };
    await db().collection('users').insertMany([adminUser, ordinary]);
    token = (await createSession(adminUser)).accessToken; userToken = (await createSession(ordinary)).accessToken;
    await db().collection('albums').insertOne({ _id: album, title: 'Synthetic tracks Album', lifecycleStatus: 'ready', audioTrackIds: [] });
});
after(async () => { await new Promise<void>(resolve => server?.close(() => resolve())); await harness?.stop(); });

test('members follow the declared Album order with each lifecycle state and only allowlisted fields', async () => {
    const ids = Array.from({ length: 10 }, () => new ObjectId()), missing = new ObjectId();
    const [first, video, pending, failed, deleting, unpublished, unavailable, legacy, deletingNow, unsetPublication] = ids;
    // Listeners still receive a declared member linked to another ready public Album; a review of this Album refuses it.
    const otherAlbum = new ObjectId();
    await db().collection('albums').insertOne({ _id: otherAlbum, title: 'Synthetic other Album', lifecycleStatus: 'ready', audioTrackIds: [] });
    const { publicationStatus: _published, ...legacyRow } = track(legacy, 'Synthetic legacy', { s3Key: legacy.toHexString(), discNumber: 1000, albumId: otherAlbum.toHexString() });
    const { albumId: _linked, ...unlinkedRow } = track(deletingNow, 'Synthetic deleting now', { uploadStatus: 'deleting' });
    await db().collection('audioTracks').insertMany([
        track(first, 'Synthetic first', { discNumber: 1, discNumberSource: 'embedded', trackNumber: 2, duration: '03:05' }),
        track(video, 'Synthetic hidden video', { albumId: album, mediaType: 'video', contentType: 'video/mp4', s3Key: `video/${video}/${new ObjectId()}`, visibility: 'hidden', discNumber: 2, trackNumber: 1, duration: '1:02:03' }),
        track(pending, 'Synthetic pending', { uploadStatus: 'pending', publicationStatus: 'pending' }),
        track(failed, 'Synthetic failed', { uploadStatus: 'failed', duration: 'later' }),
        track(deleting, 'Synthetic deleting', { uploadStatus: 'deleteFailed' }),
        track(unpublished, 'Synthetic unpublished', { publicationStatus: 'failed' }),
        track(unavailable, 'Synthetic unavailable', { s3Key: `audio/${new ObjectId()}/${new ObjectId()}`, trackNumber: 0 }),
        // A legacy row: no publication status, its identity key, an invalid stored Disc Number and a link to another Album.
        legacyRow,
        // Being deleted, without any Album link of its own.
        unlinkedRow,
        // A null publication status is not the absent legacy one, so the ready filter refuses it.
        track(unsetPublication, 'Synthetic null publication', { publicationStatus: null })
    ]);
    // The listener read skips malformed and repeated IDs and accepts any case; so does this one.
    const declared = [first.toHexString(), 'not-an-object-id', video.toHexString().toUpperCase(), pending.toHexString(), first.toHexString(),
        failed.toHexString(), deleting.toHexString(), unpublished.toHexString(), unavailable.toHexString(), missing.toHexString(), legacy.toHexString(),
        deletingNow.toHexString(), unsetPublication.toHexString()];
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: declared } });
    const albumBefore = await db().collection('albums').findOne({ _id: album });
    const snapshotBefore = (await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item.revision;

    const response = await read(album.toHexString());
    assert.equal(response.status, 200); assert.match(response.headers.get('cache-control')!, /no-store/);
    const wire = await response.text(), body = JSON.parse(wire);
    assert.deepEqual(Object.keys(body).sort(), ['albumId', 'expected', 'order', 'skipped', 'tracks', 'truncated']);
    assert.equal(body.expected, null);
    // The malformed entry and the repeated first ID are counted, as a review of this membership would refuse them.
    assert.deepEqual({ albumId: body.albumId, order: body.order, truncated: body.truncated, skipped: body.skipped },
        { albumId: album.toHexString(), order: 'declared', truncated: false, skipped: 2 });
    const row = (id: ObjectId, position: number, extra: Record<string, unknown>) => ({ position, id: id.toHexString(), discNumber: null, trackNumber: null,
        duration: null, mediaType: 'audio', visibility: 'public', state: 'ready', linkedElsewhere: false, ...extra });
    assert.deepEqual(body.tracks, [
        row(first, 1, { title: 'Synthetic first', discNumber: 1, trackNumber: 2, duration: '03:05' }),
        row(video, 2, { title: 'Synthetic hidden video', discNumber: 2, trackNumber: 1, duration: '1:02:03', mediaType: 'video', visibility: 'hidden' }),
        row(pending, 3, { title: 'Synthetic pending', state: 'pending' }),
        row(failed, 4, { title: 'Synthetic failed', state: 'failed' }),
        row(deleting, 5, { title: 'Synthetic deleting', state: 'deleting' }),
        row(unpublished, 6, { title: 'Synthetic unpublished', state: 'unpublished' }),
        row(unavailable, 7, { title: 'Synthetic unavailable', state: 'unavailable' }),
        { position: 8, id: missing.toHexString(), state: 'missing' },
        row(legacy, 9, { title: 'Synthetic legacy', linkedElsewhere: true }),
        row(deletingNow, 10, { title: 'Synthetic deleting now', state: 'deleting', linkedElsewhere: true }),
        row(unsetPublication, 11, { title: 'Synthetic null publication', state: 'unpublished' })
    ]);
    for (const secret of ['s3Key', 'audio/', 'video/', 'private-source-name', 'originalFileName', 'createdBy', 'contentType', 'musicBrainzId',
        '11111111-2222', 'coverArt', 'https:', 'mediaUrl', 'uploadStatus', 'publicationStatus', 'revision']) assert.equal(wire.includes(secret), false, secret);

    // A read-only projection: the Album record, its catalog revision and every member stay unchanged.
    assert.deepEqual(await db().collection('albums').findOne({ _id: album }), albumBefore);
    assert.equal((await getAdminCatalogItem(admin.toHexString(), 'album', album.toHexString())).item.revision, snapshotBefore);
    assert.equal(adminCatalogItemRevision('album', albumBefore), snapshotBefore);
    // Listeners receive the public ready members in the same relative order.
    const listener = await getListenerAlbum(album.toHexString());
    assert.deepEqual(listener?.tracks.map(value => value.id), body.tracks.filter((value: any) => value.state === 'ready' && value.visibility === 'public').map((value: any) => value.id));
});

test('an empty Album lists no members, and an oversized membership reads only its leading bound', async () => {
    assert.deepEqual(await getAdminCatalogAlbumTracks(admin.toHexString(), album.toHexString()), { albumId: album.toHexString(), order: 'declared', truncated: false, skipped: 0, tracks: [], expected: null });
    await db().collection('albums').updateOne({ _id: album }, { $unset: { audioTrackIds: '' } });
    assert.deepEqual((await getAdminCatalogAlbumTracks(admin.toHexString(), album.toHexString())).tracks, []);
    // A membership of only malformed entries lists nothing, but reports the entries that need repair.
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: ['not-an-id'] } });
    assert.deepEqual(await getAdminCatalogAlbumTracks(admin.toHexString(), album.toHexString()), { albumId: album.toHexString(), order: 'declared', truncated: false, skipped: 1, tracks: [], expected: null });
    // Entries past the read bound are neither listed nor counted.
    const declared = [...Array.from({ length: ADMIN_ALBUM_TRACKS_LIMIT }, () => new ObjectId().toHexString()), 'not-an-id'];
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: declared } });
    const result = await getAdminCatalogAlbumTracks(admin.toHexString(), album.toHexString());
    assert.equal(result.truncated, true); assert.equal(result.skipped, 0); assert.equal(result.tracks.length, ADMIN_ALBUM_TRACKS_LIMIT);
    assert.deepEqual(result.tracks.at(-1), { position: ADMIN_ALBUM_TRACKS_LIMIT, id: declared[ADMIN_ALBUM_TRACKS_LIMIT - 1], state: 'missing' });
});

test('a legacy Album without declared IDs lists its ready linked MediaTracks by title, as listeners receive them', async () => {
    const legacyAlbum = new ObjectId(), [beta, alpha, hidden, pending] = Array.from({ length: 4 }, () => new ObjectId());
    await db().collection('albums').insertOne({ _id: legacyAlbum, title: 'Synthetic legacy Album' });
    await db().collection('audioTracks').insertMany([
        track(beta, 'Beta', { albumId: legacyAlbum.toHexString() }), track(alpha, 'Alpha', { albumId: legacyAlbum.toHexString().toUpperCase() }),
        track(hidden, 'Gamma', { albumId: legacyAlbum, visibility: 'hidden' }), track(pending, 'Aardvark', { albumId: legacyAlbum.toHexString(), uploadStatus: 'pending' })
    ]);
    const result = await getAdminCatalogAlbumTracks(admin.toHexString(), legacyAlbum.toHexString());
    assert.equal(result.order, 'legacyAlbumLinks'); assert.equal(result.skipped, 0);
    // Every legacy member is found by its link to this Album, whatever case or type stores it.
    assert.equal(result.tracks.every(value => 'linkedElsewhere' in value && !value.linkedElsewhere), true);
    assert.deepEqual(result.tracks.map(value => [value.position, value.id, value.state, 'visibility' in value ? value.visibility : null]),
        [[1, alpha.toHexString(), 'ready', 'public'], [2, beta.toHexString(), 'ready', 'public'], [3, hidden.toHexString(), 'ready', 'hidden']]);
    assert.deepEqual((await getListenerAlbum(legacyAlbum.toHexString()))?.tracks.map(value => value.id), [alpha, beta].map(id => id.toHexString()));
    // A ready Album that declares no members stays empty: the fallback is only for legacy records.
    await db().collection('audioTracks').updateOne({ _id: beta }, { $set: { albumId: album.toHexString() } });
    assert.deepEqual((await getAdminCatalogAlbumTracks(admin.toHexString(), album.toHexString())).tracks, []);
});

test('only a current administrator reads members, and only of a ready Album', async () => {
    assert.equal((await read(album.toHexString(), '')).status, 401);
    assert.equal((await read(album.toHexString(), userToken)).status, 403);
    assert.equal((await read('not-an-id')).status, 400);
    const absent = await read(new ObjectId().toHexString());
    assert.equal(absent.status, 404); assert.deepEqual(await absent.json(), { code: 'ADMIN_CATALOG_NOT_FOUND' });
    await db().collection('albums').updateOne({ _id: album }, { $set: { lifecycleStatus: 'deleting' } });
    assert.equal((await read(album.toHexString())).status, 404);
    await db().collection('albums').updateOne({ _id: album }, { $set: { lifecycleStatus: 'ready' } });
    assert.equal((await read(album.toHexString())).status, 200);
    // Administrators still read the members of a hidden Album, which listeners cannot open.
    await db().collection('albums').updateOne({ _id: album }, { $set: { visibility: 'hidden' } });
    assert.equal((await read(album.toHexString())).status, 200);
    await db().collection('users').updateOne({ _id: admin }, { $set: { role: 'user' } });
    assert.equal((await read(album.toHexString())).status, 403);
    await assert.rejects(getAdminCatalogAlbumTracks(admin.toHexString(), album.toHexString()), (error: any) => error.code === 'ADMIN_PERMISSION_REQUIRED');
});

test('expected rows place members by Disc and Track Number whatever their state or visibility, and a row without one has no file', async () => {
    const [ready, hidden, pending, invalidDisc, deleting, sharedFirst, sharedSecond, beyond, unnumbered] = Array.from({ length: 9 }, () => new ObjectId());
    const dangling = new ObjectId();
    await db().collection('audioTracks').insertMany([
        track(ready, 'Synthetic ready', { discNumber: 1, trackNumber: 1 }),
        // No stored Disc Number counts as disc 1.
        track(hidden, 'Synthetic hidden', { visibility: 'hidden', trackNumber: 2 }),
        track(pending, 'Synthetic pending', { uploadStatus: 'pending', publicationStatus: 'pending', discNumber: 1, trackNumber: 3 }),
        // An invalid stored Disc Number counts as disc 1 too.
        track(invalidDisc, 'Synthetic invalid disc', { discNumber: 'x', trackNumber: 4 }),
        track(deleting, 'Synthetic deleting', { uploadStatus: 'deleting', discNumber: 2, trackNumber: 1 }),
        track(sharedFirst, 'Synthetic shared first', { discNumber: 2, trackNumber: 3 }),
        track(sharedSecond, 'Synthetic shared second', { discNumber: 2, trackNumber: 3 }),
        track(beyond, 'Synthetic beyond the tracklist', { discNumber: 2, trackNumber: 9 }),
        track(unnumbered, 'Synthetic unnumbered', { discNumber: 2 })
    ]);
    // Declared order decides the order of a row's members and of the members outside it.
    const declared = [ready, hidden, pending, invalidDisc, unnumbered, dangling, deleting, sharedSecond, sharedFirst, beyond].map(hex);
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: declared } });
    const withoutTracklist = await (await read(hex(album))).json();
    assert.equal(withoutTracklist.expected, null);

    const rows = [row(1, 1, 185_000), row(1, 2), row(1, 3, 61_000), row(1, 4), row(2, 1, 3_600_000), row(2, 2, 1), row(2, 3, 240_000)];
    await storeTracklist(tracklist(rows));
    const albumBefore = await db().collection('albums').findOne({ _id: album });
    const revisionBefore = (await getAdminCatalogItem(hex(admin), 'album', hex(album))).item.revision;
    const response = await read(hex(album));
    assert.equal(response.status, 200);
    const body = await response.json();
    assert.deepEqual(Object.keys(body), ['albumId', 'order', 'truncated', 'skipped', 'tracks', 'expected']);
    const members: Record<string, string[]> = { '1:1': [hex(ready)], '1:2': [hex(hidden)], '1:3': [hex(pending)], '1:4': [hex(invalidDisc)],
        '2:1': [hex(deleting)], '2:2': [], '2:3': [hex(sharedSecond), hex(sharedFirst)] };
    assert.deepEqual(body.expected, { source: 'musicbrainz', appliedAt: '2026-10-20T08:00:00.000Z',
        rows: rows.map(value => ({ ...value, memberIds: members[`${value.discNumber}:${value.trackNumber}`] })),
        // The dangling declared ID is in neither list; it stays a missing member of the Album order.
        outsideMemberIds: [hex(unnumbered), hex(beyond)] });
    // The Album order, its numbering and every member state are exactly those of an Album without a tracklist.
    assert.equal(JSON.stringify(body.tracks), JSON.stringify(withoutTracklist.tracks));
    assert.deepEqual(body.tracks.find((value: any) => value.id === hex(dangling)), { position: 6, id: hex(dangling), state: 'missing' });
    // A read writes nothing and changes no revision.
    assert.deepEqual(await db().collection('albums').findOne({ _id: album }), albumBefore);
    assert.equal((await getAdminCatalogItem(hex(admin), 'album', hex(album))).item.revision, revisionBefore);
});

test('renumbering, unlinking and deleting members change which rows have a file, never the stored tracklist', async () => {
    const [first, second, third, beyond] = Array.from({ length: 4 }, () => new ObjectId());
    await db().collection('audioTracks').insertMany([
        track(first, 'Synthetic first', { discNumber: 1, trackNumber: 1 }), track(second, 'Synthetic second', { discNumber: 1, trackNumber: 2 }),
        track(third, 'Synthetic third', { discNumber: 2, trackNumber: 1 }), track(beyond, 'Synthetic beyond', { discNumber: 2, trackNumber: 9 })
    ]);
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [first, second, third, beyond].map(hex) } });
    const stored = tracklist([row(1, 1), row(1, 2), row(2, 1), row(2, 2)]);
    await storeTracklist(stored);
    const placement = async () => {
        const { expected } = await getAdminCatalogAlbumTracks(hex(admin), hex(album));
        assert.ok(expected);
        assert.deepEqual((await db().collection('albums').findOne({ _id: album }))!.expectedTracklist, stored);
        return { rows: expected.rows.map(value => [`${value.discNumber}:${value.trackNumber}`, value.memberIds]), outside: expected.outsideMemberIds };
    };
    assert.deepEqual(await placement(), { rows: [['1:1', [hex(first)]], ['1:2', [hex(second)]], ['2:1', [hex(third)]], ['2:2', []]], outside: [hex(beyond)] });
    // Renumbering through the catalog editor moves the outside member onto the row without a file.
    const trackRevision = (await getAdminCatalogItem(hex(admin), 'audioTrack', hex(beyond))).item.revision;
    await editAdminCatalogItem(hex(admin), 'audioTrack', hex(beyond), { operationId: randomUUID(), expectedRevision: trackRevision, fields: { discNumber: 2, trackNumber: 2 } });
    assert.deepEqual(await placement(), { rows: [['1:1', [hex(first)]], ['1:2', [hex(second)]], ['2:1', [hex(third)]], ['2:2', [hex(beyond)]]], outside: [] });
    // Unlinking a member leaves its row without a file; it is no longer listed, so it is not outside either.
    await db().collection('albums').updateOne({ _id: album }, { $pull: { audioTrackIds: hex(second) } } as any);
    assert.deepEqual(await placement(), { rows: [['1:1', [hex(first)]], ['1:2', []], ['2:1', [hex(third)]], ['2:2', [hex(beyond)]]], outside: [] });
    // Deleting a member's record makes it a missing member of the Album order and leaves its row without a file.
    await db().collection('audioTracks').deleteOne({ _id: third });
    assert.deepEqual(await placement(), { rows: [['1:1', [hex(first)]], ['1:2', []], ['2:1', []], ['2:2', [hex(beyond)]]], outside: [] });
    const { tracks } = await getAdminCatalogAlbumTracks(hex(admin), hex(album));
    assert.deepEqual(tracks.find(value => value.id === hex(third)), { position: 2, id: hex(third), state: 'missing' });
});

test('an iTunes, malformed, empty-Album, hidden-Album, legacy and oversized read', async () => {
    const [member, legacyReady, legacyHidden, legacyPending] = Array.from({ length: 4 }, () => new ObjectId());
    await db().collection('audioTracks').insertOne(track(member, 'Synthetic member', { discNumber: 1, trackNumber: 1 }));
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [hex(member)] } });
    const plain = await getAdminCatalogAlbumTracks(hex(admin), hex(album));
    // An iTunes-only tracklist keeps its source.
    await storeTracklist(tracklist([row(1, 1), row(1, 2)], 'itunes'));
    const itunes = await getAdminCatalogAlbumTracks(hex(admin), hex(album));
    assert.equal(itunes.expected?.source, 'itunes'); assert.deepEqual(itunes.expected?.rows.map(value => value.memberIds), [[hex(member)], []]);
    // A malformed stored value reads as none and leaves the member list as it is.
    await storeTracklist({ ...tracklist([row(1, 1)]), source: 'other' });
    assert.deepEqual(await getAdminCatalogAlbumTracks(hex(admin), hex(album)), plain);
    // So does an applied instant whose year needs the expanded ISO 8601 form, past 9999 or before 0000.
    for (const appliedAt of [new Date('+010000-01-01T00:00:00.000Z'), new Date('-000001-01-01T00:00:00.000Z')]) {
        await storeTracklist({ ...tracklist([row(1, 1)]), appliedAt });
        assert.deepEqual(await getAdminCatalogAlbumTracks(hex(admin), hex(album)), plain);
    }
    // The last four-digit year still reads.
    await storeTracklist({ ...tracklist([row(1, 1)]), appliedAt: new Date('9999-12-31T23:59:59.999Z') });
    assert.equal((await getAdminCatalogAlbumTracks(hex(admin), hex(album))).expected?.appliedAt, '9999-12-31T23:59:59.999Z');
    // A hidden Album still shows its tracklist to administrators.
    await storeTracklist(tracklist([row(1, 1), row(1, 2)]));
    await db().collection('albums').updateOne({ _id: album }, { $set: { visibility: 'hidden' } });
    assert.deepEqual((await getAdminCatalogAlbumTracks(hex(admin), hex(album))).expected?.rows.map(value => value.memberIds), [[hex(member)], []]);
    // An empty Album has every row without a file and nothing outside.
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [] } });
    const empty = await getAdminCatalogAlbumTracks(hex(admin), hex(album));
    assert.deepEqual(empty.tracks, []); assert.deepEqual(empty.expected?.rows.map(value => value.memberIds), [[], []]); assert.deepEqual(empty.expected?.outsideMemberIds, []);
    // A legacy Album matches only the ready linked MediaTracks it lists; a linked pending upload is not listed, so its row has no file.
    const legacyAlbum = new ObjectId();
    await db().collection('albums').insertOne({ _id: legacyAlbum, title: 'Synthetic legacy Album', expectedTracklist: tracklist([row(1, 1), row(1, 2), row(1, 3)]) });
    await db().collection('audioTracks').insertMany([
        track(legacyReady, 'Alpha', { albumId: hex(legacyAlbum), discNumber: 1, trackNumber: 2 }),
        track(legacyHidden, 'Beta', { albumId: hex(legacyAlbum), visibility: 'hidden', trackNumber: 7 }),
        track(legacyPending, 'Gamma', { albumId: hex(legacyAlbum), uploadStatus: 'pending', trackNumber: 1 })
    ]);
    const legacy = await getAdminCatalogAlbumTracks(hex(admin), hex(legacyAlbum));
    assert.equal(legacy.order, 'legacyAlbumLinks');
    assert.deepEqual(legacy.tracks.map(value => value.id), [hex(legacyReady), hex(legacyHidden)]);
    assert.deepEqual(legacy.expected?.rows.map(value => value.memberIds), [[], [hex(legacyReady)], []]);
    assert.deepEqual(legacy.expected?.outsideMemberIds, [hex(legacyHidden)]);
    // Past the read bound nothing more is matched; IDs without records fill no row.
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: Array.from({ length: ADMIN_ALBUM_TRACKS_LIMIT + 1 }, () => hex(new ObjectId())) } });
    const oversized = await getAdminCatalogAlbumTracks(hex(admin), hex(album));
    assert.equal(oversized.truncated, true); assert.equal(oversized.tracks.length, ADMIN_ALBUM_TRACKS_LIMIT);
    assert.deepEqual(oversized.expected?.rows.map(value => value.memberIds), [[], []]); assert.deepEqual(oversized.expected?.outsideMemberIds, []);
});

test('only administrators read expected rows, and listeners receive nothing new', async () => {
    const member = new ObjectId();
    await db().collection('audioTracks').insertOne(track(member, 'Synthetic listener track', { discNumber: 1, trackNumber: 1 }));
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: [hex(member)] } });
    const listenerBefore = await getListenerAlbum(hex(album));
    await storeTracklist({ ...tracklist([row(1, 1), row(1, 2)]), rows: [
        { discNumber: 1, trackNumber: 1, title: 'Unheard admin row one', durationMs: null }, { discNumber: 1, trackNumber: 2, title: 'Unheard admin row two', durationMs: null }] });
    for (const [access, status] of [[userToken, 403], ['', 401]] as const) {
        const response = await read(hex(album), access);
        assert.equal(response.status, status); assert.equal((await response.text()).includes('Unheard'), false);
    }
    const admitted = await (await read(hex(album))).json();
    assert.deepEqual(admitted.expected.rows.map((value: any) => value.title), ['Unheard admin row one', 'Unheard admin row two']);
    const listenerAfter = await getListenerAlbum(hex(album));
    assert.deepEqual(listenerAfter?.tracks.map(value => value.id), [hex(member)]);
    assert.deepEqual(listenerAfter?.tracks.map(value => value.id), listenerBefore?.tracks.map(value => value.id));
    assert.equal(JSON.stringify(listenerAfter).includes('Unheard'), false);
    assert.equal(JSON.stringify(listenerAfter).includes('expectedTracklist'), false);
});
